SOURCE = "def invoke(evaluator, action, value, group=None):\n    from .suspension import Task, Await, Generator\n    from .iteration import HANDLES\n    before=len(evaluator.suspension.tasks)\n    result=yield from evaluator._s_invoke(action,[value])\n    if isinstance(result,Task):\n        evaluator.suspension.validate(result,Task)\n        current=evaluator.suspension.current.task\n        if current.recording_scope is not None and result.recording_scope!=current.recording_scope:\n            raise LanguageError('录制不能等待来自其他 scope 的 Task',code='mode_error')\n        if group is not None:\n            # A returned cold async operation belongs to this invocation. A\n            # borrowed Task remains a non-owning await, even if still cold.\n            # The helper checks parent identity, not merely the global slice:\n            # another cooperative action may have created Tasks in that slice.\n            from .contexts import _operation\n            if _operation(evaluator,result,evaluator.suspension.tasks[before:]):\n                group.spawn(result)\n        result=yield Await(result)\n    if isinstance(result,(Task,Generator)+HANDLES): raise LanguageError('模式 action 不能返回未消费的 Task/stream',code='mode_error')\n    return result\n\ndef host(evaluator, operation, payload):\n    from .suspension import Effect\n    if evaluator.mode_handler is None: raise LanguageError('当前上下文没有模式持久化/录制能力',code='capability_error')\n    evaluator.tick()\n    result=yield Effect('mode',{'operation':operation,'payload':data(payload)})\n    evaluator.tick()\n    return data(result)\n\ndef _plan_error_event(evaluator, event, error, metadata, **payload):\n    # Trace observers must not downgrade the control failure being unwound.\n    from .suspension import error_priority\n    try:emit(evaluator,event,errorCode=getattr(error,'code',None),**metadata,**payload)\n    except BaseException as trace_error:\n        if error_priority(trace_error)>error_priority(error):raise\n\ndef _plan_step(evaluator, step, action, context, metadata, group=None):\n    payload={'stepId':step['id'],'call':step['call']}\n    if group is not None:payload['stepTaskId']=evaluator.suspension.current.task.id\n    try:\n        emit(evaluator,'plan.step.started',**metadata,**payload)\n        result=data((yield from invoke(evaluator,action,context,group)))\n        emit(evaluator,'plan.step.completed',**metadata,**payload)\n        return result\n    except BaseException as error:\n        event='plan.step.cancelled' if isinstance(error,(ExecutionControl,GeneratorExit)) else 'plan.step.failed'\n        _plan_error_event(evaluator,event,error,metadata,**payload)\n        raise\n\ndef _serial_plan(evaluator, definition, actions, input, metadata):\n    results={}\n    # Preserve the legacy scan order exactly. Restarting this scan after each\n    # completion would change order for existing serial dependency graphs.\n    while len(results)<len(definition['steps']):\n        for step in definition['steps']:\n            evaluator.tick()\n            if step['id'] in results or not all(name in results for name in step['needs']):continue\n            context={'input':data(input),'results':{name:data(results[name]) for name in step['needs']}}\n            results[step['id']]=yield from _plan_step(evaluator,step,actions[step['call']],context,metadata)\n            results=data(results)\n    return results\n\ndef _parallel_plan(evaluator, definition, actions, input, metadata):\n    from .suspension import Await, TERMINAL\n    from .task_groups import create, GroupRun, ScopeOutcome\n    from .task_waits import wait\n    scheduler=evaluator.suspension\n    group=create(evaluator)\n    def body():\n        results={};pending={};admitted=set()\n        try:\n            while len(results)<len(definition['steps']):\n                evaluator.tick()\n                # Commit all available completions before scanning readiness.\n                # The group interrupts this body on any member failure, so\n                # no additional step is admitted after a committed failure.\n                for step_id,task in list(pending.items()):\n                    if task.state not in TERMINAL:continue\n                    if task.runner.error is not None:raise task.runner.error\n                    results[step_id]=task.runner.result\n                    del pending[step_id]\n                results=data(results)\n                for step in definition['steps']:\n                    evaluator.tick()\n                    if len(pending)>=metadata['maxConcurrency']:break\n                    if step['id'] in admitted or not all(name in results for name in step['needs']):continue\n                    context={'input':data(input),'results':{name:data(results[name]) for name in step['needs']}}\n                    task=scheduler.task(_plan_step(evaluator,step,actions[step['call']],context,metadata,group), capture_roots=(actions[step['call']],context,group))\n                    group.spawn(task)\n                    pending[step['id']]=task;admitted.add(step['id'])\n                if pending:yield Await(wait(evaluator,list(pending.values())))\n            # Concurrent completion never changes the public result key order.\n            return ScopeOutcome(value={step['id']:results[step['id']] for step in definition['steps']})\n        except BaseException as error:\n            return ScopeOutcome(error=error)\n    outcome=yield GroupRun(group,body())\n    return outcome.value\n\ndef run_plan(evaluator, value, bindings, input):\n    definition=owned(value,evaluator,Plan).definition\n    actions=bindings_for(evaluator,bindings,dict.fromkeys(step['call'] for step in definition['steps']))\n    input=data(input)\n    metadata={'executionId':'plan-'+uuid.uuid4().hex,\n              'name':definition['name'],'definitionHash':definition_hash(definition),\n              'maxConcurrency':definition.get('max_concurrency',1)}\n    try:\n        emit(evaluator,'plan.started',steps=len(definition['steps']),**metadata)\n        execute=_serial_plan if metadata['maxConcurrency']==1 else _parallel_plan\n        result=yield from execute(evaluator,definition,actions,input,metadata)\n        emit(evaluator,'plan.completed',**metadata)\n        return result\n    except BaseException as error:\n        event='plan.cancelled' if isinstance(error,(ExecutionControl,GeneratorExit)) else 'plan.failed'\n        _plan_error_event(evaluator,event,error,metadata)\n        raise\n\ndef pursue(evaluator, value, bindings, input, key):\n    definition=owned(value,evaluator,Goal).definition\n    actions=bindings_for(evaluator,bindings,[definition['planner'],definition['verify']])\n    input=data(input);state={'iteration':0,'state':input,'results':{},'history':[],'phase':'ready','evidence':None};claim=None\n    if key is not None:\n        identifier(key,'key')\n        claim=yield from host(evaluator,'goal.claim',{'key':key,'definition':definition,'input':input})\n        state=checkpoint(claim['checkpoint'],definition)\n        if state['phase']=='pending':raise LanguageError('Goal 未完成动作需要先 reconciliation',code='mode_error')\n    def result():return {'done':state['phase']=='done','state':data(state['state']),'evidence':data(state['evidence']),'iterations':state['iteration'],'status':'achieved' if state['phase']=='done' else 'exhausted'}\n    try:\n        if state['phase'] in ('done','exhausted'):return result()\n        while state['iteration']<definition['max_iterations']:\n            evaluator.tick();state['iteration']+=1;state['phase']='pending'\n            if claim:\n                claim=yield from host(evaluator,'goal.commit',{'key':key,'lease':claim['lease'],'revision':claim['revision'],'checkpoint':state})\n            emit(evaluator,'goal.iteration',iteration=state['iteration'])\n            context={'objective':definition['objective'],'state':data(state['state']),'iteration':state['iteration'],'results':data(state['results']),'history':data(state['history'])}\n            planned=yield from invoke(evaluator,actions[definition['planner']],context)\n            owned(planned,evaluator,Plan)\n            state['results']=yield from run_plan(evaluator,planned,bindings,state['state'])\n            observation={**context,'results':data(state['results'])}\n            verification=data((yield from invoke(evaluator,actions[definition['verify']],observation)))\n            if type(verification) is not dict or set(verification)!={'done','state','evidence'} or type(verification['done']) is not bool:\n                raise LanguageError('Goal verify 需要 {done:Bool,state:JSON,evidence:JSON}',code='mode_error')\n            state['state'],state['evidence']=verification['state'],verification['evidence']\n            state['history'].append({'iteration':state['iteration'],'done':verification['done'],'evidence':data(verification['evidence'])})\n            state['phase']='done' if verification['done'] else ('exhausted' if state['iteration']>=definition['max_iterations'] else 'ready')\n            state=checkpoint(state,definition)\n            if claim:claim=yield from host(evaluator,'goal.commit',{'key':key,'lease':claim['lease'],'revision':claim['revision'],'checkpoint':state})\n            emit(evaluator,'goal.verified',iteration=state['iteration'],done=verification['done'])\n            if verification['done']:break\n        emit(evaluator,'goal.completed',status=result()['status'],iterations=state['iteration'])\n        return result()\n    except (ResourceLimit,ExecutionControl,GeneratorExit):raise\n    except BaseException:\n        if claim:\n            try:yield from host(evaluator,'goal.release',{'key':key,'lease':claim['lease'],'outcome':'failed'})\n            except BaseException:pass\n        raise\n\ndef record(evaluator, action, input, parameters):\n    from .suspension import Await, Drain, TERMINAL, TaskCancelled, AsyncGenerator, hard_error, error_priority\n    from .iteration import AsyncIterator\n    from .resource_stacks import finalize_scope\n    from .contexts import abandon as abandon_context\n    check_type(action,'Function');input=data(input);parameters=data(parameters)\n    task=evaluator.suspension.current.task\n    if task.recording_scope is not None:raise LanguageError('暂不支持嵌套录制 scope',code='mode_error')\n    opened=yield from host(evaluator,'recording.begin',{})\n    scope=opened['scopeId'];task.recording_scope=scope\n    def close_resources():\n        # Close lexical owners before orphaned resource stacks. A stack-created\n        # generator belongs to its captured exit and cannot be consumed here.\n        streams=[handle for handle in evaluator.suspension.generators if handle.recording_scope==scope and handle.state not in TERMINAL and handle.context_manager is None]\n        adapters=[handle for handle in evaluator.suspension.iteration.handles if handle.recording_scope==scope and not handle.close_attempted]\n        for handle in streams+adapters:\n            evaluator.tick()\n            if isinstance(handle,(AsyncGenerator,AsyncIterator)):\n                yield Await(evaluator.suspension.aclose(handle))\n            elif handle in streams:\n                yield from evaluator.suspension._s_close(handle)\n            else:\n                yield from evaluator.suspension.iteration.close(handle)\n        stacks=yield from finalize_scope(evaluator,scope)\n        return bool(streams or adapters or stacks)\n    try:\n        output=yield from invoke(evaluator,action,input)\n        # Children may create further children while being joined. Cold children\n        # are cancelled without executing; started descendants finish before seal.\n        seen=set()\n        while True:\n            children=[child for child in evaluator.suspension.tasks if child is not task and child.recording_scope==scope and id(child) not in seen]\n            for child in children:\n                seen.add(id(child))\n                if child.state=='created':\n                    evaluator.suspension.cancel(child)\n                    child.observed=True\n                    try: yield Await(child)\n                    except TaskCancelled: pass\n                    continue\n                if child.state=='cancelled':raise LanguageError('录制子 Task 已取消',code='mode_error')\n                child.observed=True\n                if child.state not in TERMINAL or child.state=='failed':yield Await(child)\n            resources=yield from close_resources()\n            if not children and not resources:break\n        for handle in evaluator.suspension.generators:\n            if handle.recording_scope==scope and handle.context_manager is not None and handle.state not in TERMINAL:\n                abandon_context(evaluator,handle.context_manager)\n        output=data(output)\n        finished=yield from host(evaluator,'recording.finish',{'scopeId':scope,'parameters':parameters})\n        skill=make(finished['definition'],evaluator)\n        if not isinstance(skill,Skill):raise LanguageError('录制没有返回 Skill',code='mode_error')\n        return {'output':output,'skill':skill}\n    except (ResourceLimit,ExecutionControl,GeneratorExit):\n        for child in evaluator.suspension.tasks:\n            if child is not task and child.recording_scope==scope and child.state not in TERMINAL:evaluator.suspension.cancel(child)\n        raise\n    except BaseException as original:\n        pending=original;seen=set();cancellation=object()\n        while True:\n            children=[child for child in evaluator.suspension.tasks if child is not task and child.recording_scope==scope and id(child) not in seen]\n            for child in children:\n                seen.add(id(child))\n                if child.state not in TERMINAL:evaluator.suspension._cancel(child,cancellation)\n            if hard_error(pending):break\n            # Wait for real effect completion before cleanup/abort can seal the\n            # tape. Local cancellation is bookkeeping; independent hard errors\n            # still take priority over the action's ordinary failure.\n            for child in children:\n                child.observed=True\n                try:yield Drain(child)\n                except BaseException as drained:\n                    local=evaluator.suspension._local_cancel(drained,child) and child.cancel_sources=={cancellation}\n                    if not local and error_priority(drained)>error_priority(pending):pending=drained\n            if hard_error(pending):break\n            try:resources=yield from close_resources()\n            except BaseException as cleanup:\n                pending=cleanup;resources=True\n            if not children and not resources:break\n        if not hard_error(pending):\n            try:yield from host(evaluator,'recording.abort',{'scopeId':scope,'reason':'action_failed'})\n            except BaseException as aborted:\n                if error_priority(aborted)>error_priority(pending):pending=aborted\n        if pending is not original:raise pending\n        raise\n    finally:\n        # Nothing created in an aborted tape may execute deferred user cleanup\n        # after its recording identity is removed. Normal paths are already closed.\n        yield from finalize_scope(evaluator,scope,hard=True)\n        for handle in evaluator.suspension.generators:\n            if handle.recording_scope==scope and handle.state not in TERMINAL:\n                if handle.context_manager is not None:abandon_context(evaluator,handle.context_manager)\n                else:\n                    evaluator.suspension._abort_stream(handle);handle.state='closed';handle.busy=False\n        for handle in evaluator.suspension.iteration.handles:\n            if handle.recording_scope==scope:\n                handle.close_attempted,handle.busy,handle.state=True,False,'closed'\n        task.recording_scope=None\n\ndef replay(evaluator, value, values):\n    definition=owned(value,evaluator,Skill).definition\n    actions=substitute(definition,values);results=[]\n    for index,action in enumerate(actions):\n        evaluator.tick();emit(evaluator,'skill.step',step=index,tool=action['tool'])\n        result=yield from evaluator._s_invoke(evaluator.env.get('tool'),[action['tool'],action['input']])\n        results.append(data(result));data(results)\n    return results\n\ndef resolve(evaluator, request):\n    op,args=request.operation,request.arguments\n    if op=='run_plan':return evaluator.suspension.task(run_plan(evaluator,*args), capture_roots=tuple(args))\n    if op=='pursue':return evaluator.suspension.task(pursue(evaluator,*args), capture_roots=tuple(args))\n    if op=='record_skill':return evaluator.suspension.task(record(evaluator,*args), capture_roots=tuple(args))\n    if op=='replay_skill':return evaluator.suspension.task(replay(evaluator,*args), capture_roots=tuple(args))\n    if op in ('save_mode','load_mode'):\n        def artifact():\n            if op=='save_mode':\n                value,key,revision=args;definition=owned(value,evaluator).definition\n                payload={'key':identifier(key,'key'),'definition':definition}\n                if revision_number(revision) is not None:payload['revision']=revision\n                return (yield from host(evaluator,'artifact.save',payload))\n            key,revision=args\n            payload={'key':identifier(key,'key')}\n            if revision_number(revision) is not None:payload['revision']=revision\n            row=yield from host(evaluator,'artifact.load',payload)\n            definition=validate_definition(row['definition'])\n            if definition['kind']=='skill' and row.get('status')!='ready':\n                raise LanguageError('未完成技能不能加载为可执行值',code='mode_error')\n            origin=origin_data(row.get('origin'),definition)\n            if (origin is None or origin['key']!=key or origin['revision']!=row.get('revision')\n                    or revision is not None and origin['revision']!=revision):\n                raise LanguageError('加载来源不匹配请求的模式修订',code='mode_error')\n            return make(definition,evaluator,origin)\n        return evaluator.suspension.task(artifact())\n    raise LanguageError('未知模式操作',code='mode_error')\n"
_namespace = dict(vars(modes))
exec(compile(SOURCE, '<frozen-modes-0.136>', 'exec'), _namespace)

@contextmanager
def original_modes():
    with ExitStack() as stack:
        for name in FROZEN_FUNCTIONS:
            stack.enter_context(patch.object(modes, name, _namespace[name]))
        yield

# UUID is trace metadata only; no scheduler, tick, request or action is patched.
# Replace the module binding, not uuid.uuid4 globally. Both native and reference
# functions receive the same fresh deterministic sequence on each invocation.
@contextmanager
def fixed_execution_ids():
    index = [0]
    def uuid4():
        index[0] += 1
        return SimpleNamespace(hex=format(index[0], '032x'))
    proxy = SimpleNamespace(uuid4=uuid4)
    old = _namespace['uuid']
    _namespace['uuid'] = proxy
    try:
        with patch.object(modes, 'uuid', proxy):
            yield index
    finally:
        _namespace['uuid'] = old
